            $safe=$this->sanitizeVideo($original);$this->db->begin();$this->assertReviewableOperation($operationId);$locked=$this->one('SELECT * FROM '.MAIN_DB_PREFIX.'cpo_qc_evidence WHERE entity='.$this->entity.' AND fk_operation='.(int)$operationId.' AND rowid='.(int)$evidenceId.' FOR UPDATE');if(!$locked||$locked['upload_status']!=='reprocessing'||!hash_equals((string)$locked['original_sha256'],(string)$row['original_sha256']))throw new RuntimeException('QC evidence reprocessing state changed.');$this->verifiedEvidencePath($locked['original_stored_name'],$locked['original_size'],$locked['original_sha256']);$sql='UPDATE '.MAIN_DB_PREFIX."cpo_qc_evidence SET upload_status='finalized',upload_expires_at=NULL,safe_stored_name=".$this->q(basename($safe['path'])).',safe_mime='.$this->q($safe['mime']).',safe_size='.(int)$safe['size'].',safe_sha256='.$this->q($safe['sha256']).",review_status='pending',customer_visible=0,fk_user_review=NULL,review_note=NULL,date_review=NULL,revision=revision+1 WHERE entity=".$this->entity.' AND fk_operation='.(int)$operationId.' AND rowid='.(int)$evidenceId;if(!$this->db->query($sql))$this->fail();$this->db->commit();return array('evidence_id'=>(int)$evidenceId,'upload_status'=>'finalized','customer_safe_available'=>true,'mime'=>$safe['mime'],'sha256'=>$safe['sha256']);
        }catch(Throwable$e){$this->db->rollback();if($safe&&isset($safe['path']))@unlink($safe['path']);$this->db->query('UPDATE '.MAIN_DB_PREFIX."cpo_qc_evidence SET upload_status='internal_only',upload_expires_at=NULL WHERE entity=".$this->entity.' AND fk_operation='.(int)$operationId.' AND rowid='.(int)$evidenceId." AND upload_status='reprocessing'");throw$e;}
    }

    public function evidence($operationId){$this->recoverExpiredReprocessing($operationId);return $this->rows('SELECT rowid,fk_checkpoint,client_uuid,evidence_type,caption,upload_status,review_status,customer_visible,original_name,original_mime,original_size,original_sha256,safe_mime,safe_size,safe_sha256,revision,fk_user_creat,fk_user_review,date_review,date_finalized,date_creation FROM '.MAIN_DB_PREFIX.'cpo_qc_evidence WHERE entity='.$this->entity.' AND fk_operation='.(int)$operationId.' ORDER BY fk_checkpoint,rowid');}

