    private function probeVideo($ffprobe,$path){$run=$this->runProcess(array($ffprobe,'-v','error','-show_entries','format=duration:stream=codec_type,width,height','-of','json',$path),20);if($run['status']!==0)throw new RuntimeException('Video probe failed.');$json=json_decode($run['output'],true);if(!is_array($json))throw new RuntimeException('Video probe returned invalid data.');$out=array('duration'=>(float)($json['format']['duration']??0),'width'=>0,'height'=>0,'video_streams'=>0,'audio_streams'=>0);foreach($json['streams']??array()as$stream){if(($stream['codec_type']??'')==='video'){$out['video_streams']++;$out['width']=max($out['width'],(int)($stream['width']??0));$out['height']=max($out['height'],(int)($stream['height']??0));}elseif(($stream['codec_type']??'')==='audio')$out['audio_streams']++;}return$out;}
