    private function tempRoot(){return$this->root.'/tmp';}private function finalRoot(){return$this->root.'/evidence';}private function uploadDir($id){return$this->tempRoot().'/upload-'.(int)$id;}
    private function assertContainedDirectory($dir,$root){$realRoot=realpath($root);$realDir=realpath($dir);if(!$realRoot||!$realDir||is_link($dir)||strpos($realDir.DIRECTORY_SEPARATOR,$realRoot.DIRECTORY_SEPARATOR)!==0)throw new RuntimeException('Unsafe QC storage path.');}
