    private function manifest($json){$data=json_decode((string)$json,true);return is_array($data)?$data:array();}private function text($data,$key,$limit){$value=trim(isset($data[$key])?(string)$data[$key]:'');if(strlen($value)>$limit)throw new RuntimeException('QC evidence text is too long.');return$value!==''?$value:null;}
